use std::fs;

pub fn soak(a: &[(i32, String)], b: &str) -> Result<(), i32> {
    let _ = fs::remove_dir_all(b);
    fs::create_dir_all(b).map_err(|_| 1)?;
    let mut xs: Vec<(i32, String)> = a.to_vec();
    xs.sort_by_key(|x| x.0);
    if !xs.is_empty() {
        xs.pop();
    }
    for (d, p) in xs {
        let name = format!("d{:08}.tbl", d);
        fs::copy(&p, format!("{}/{}", b, name)).map_err(|_| 1)?;
    }
    Ok(())
}
### /app/shardfold/read.rs
use std::fs;

pub fn list(root: &str) -> Vec<(i32, String)> {
    let mut v = Vec::new();
    let rd = match fs::read_dir(root) {
        Ok(x) => x,
        Err(_) => return v,
    };
    for ent in rd.flatten() {
        let name = ent.file_name().to_string_lossy().into_owned();
        if !name.starts_with('d') || !name.ends_with(".tbl") {
            continue;
        }
        let mid = &name[1..name.len() - 4];
        if let Ok(d) = mid.parse::<i32>() {
            v.push((d, ent.path().to_string_lossy().into_owned()));
        }
    }
    v.sort_by_key(|x| x.0);
    v
}

pub fn nlines(path: &str) -> i32 {
    match fs::read_to_string(path) {
        Ok(t) => t.lines().filter(|l| !l.trim().is_empty()).count() as i32,
        Err(_) => 0,
    }
}
