use std::fs;

fn json_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn emit(probe: &str, matched: i32, taken: i32) -> Result<(), i32> {
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    let body = format!(
        "{{\"probe\":{},\"matched\":{},\"taken\":{}}}",
        json_string(probe), matched, taken
    );
    fs::write("/app/bloturn/check.json", body).map_err(|_| 1)
}

pub fn gait(taken: i32, files: &[(i32, String)], floor_ok: bool) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    if files.is_empty() {
        return 1;
    }

    // Independently reopen and count the original daywell files.  Do not use
    // ledger.json or staged copies as the verification source.
    let mut matched = 0i32;
    for (_, path) in files {
        if !path.starts_with("/app/daywell/") {
            return 1;
        }
        let text = match fs::read_to_string(path) {
            Ok(text) => text,
            Err(_) => return 1,
        };
        matched += text.lines().filter(|line| !line.trim().is_empty()).count() as i32;
    }

    if matched != taken || !floor_ok {
        return 1;
    }
    let probe = match files.iter().max_by_key(|(day, _)| *day) {
        Some((_, path)) => path.as_str(),
        None => return 1,
    };
    if emit(probe, matched, taken).is_err() {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
EOF

